-- ---------------------------------------------------------------------------
-- 0028 — geo groundwork: ZIP centroids, airport coordinates, address backfill.
--
-- WHY THIS EXISTS
--
-- Koolee had no coordinates anywhere. `addresses.lat/lng` existed since 0000
-- and no insert path ever wrote them; `airports` had no lat/lng column at
-- all. That left the drive-time estimate as a hardcoded 60 minutes
-- (`config.ts` DEFAULTS.driveTimeMinutes) and the pricing distance as a
-- hardcoded 20 km, and it is the reason a haversine ETA could not be written:
-- it needs two points and there were zero.
--
-- This migration supplies both ends of the line, at ZIP resolution:
--   * `zip_centroids` — static reference data, US Census 2023 ZCTA gazetteer
--     internal points for NY prefixes 100-119 and NJ 070-079, plus one
--     hand-entered row for 10281 (a single-building ZIP with no ZCTA).
--     Source, filter and regeneration recipe: packages/db/src/zip-centroids.ts.
--   * `airports.lat/lng` — the three terminal complexes, hardcoded. They do
--     not move.
--
-- WHY THE DATA SHIPS INSIDE THE MIGRATION, not only in the seed
--
-- Step 5 backfills existing address rows by joining `zip_centroids`, and a
-- migration cannot depend on a seed having been run first. The seed carries
-- the same payload and reconciles the table on every run, so the file remains
-- the source of truth and this is a snapshot taken to make the backfill work.
--
-- WHAT THIS DOES NOT DO
--
-- No geocoder, no Places autocomplete, no funnel change. A ZIP centroid is a
-- deliberately coarse answer to "roughly how far is this driver", and the
-- wrong resolution for anything that needs a doorstep. When real geocoding
-- lands, `ensureAddress` will take the precise coordinates it already accepts
-- and the centroid becomes the fallback.
--
-- LOCKS / BLAST RADIUS, per statement:
--   1. CREATE TABLE — new relation, nothing to block.
--   2. ENABLE ROW LEVEL SECURITY — catalog flag flip; no scan, no rewrite.
--      Idempotent, and a no-op where the `ensure_rls` event trigger already
--      fired (see 0016 and 0022 for why both paths have to be covered).
--   3. INSERT 837 reference rows — one statement, sub-second.
--   4. airports: ADD COLUMN nullable (catalog-only) -> UPDATE 3 rows ->
--      SET NOT NULL (ACCESS EXCLUSIVE + one scan of a three-row table) ->
--      two CHECKs (one scan each). The nullable-then-constrain shape is the
--      0021 pattern: Drizzle generated a bare `ADD COLUMN ... NOT NULL`,
--      which fails outright against existing rows.
--   5. addresses backfill — UPDATE ... FROM a primary-key join, touching only
--      rows whose lat IS NULL. Rows whose ZIP has no centroid stay NULL by
--      design and are counted in a NOTICE rather than failing the migration.
-- ---------------------------------------------------------------------------

CREATE TABLE "zip_centroids" (
	"zip" varchar(5) PRIMARY KEY NOT NULL,
	"lat" double precision NOT NULL,
	"lng" double precision NOT NULL,
	CONSTRAINT "zip_centroids_lat_range_check" CHECK ("zip_centroids"."lat" between -90 and 90),
	CONSTRAINT "zip_centroids_lng_range_check" CHECK ("zip_centroids"."lng" between -180 and 180)
);
--> statement-breakpoint

ALTER TABLE public.zip_centroids ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint

-- Generated from packages/db/src/zip-centroids.ts — do not hand-edit; edit
-- that file and regenerate if this ever needs to change.
ON CONFLICT (zip) DO UPDATE SET lat = excluded.lat, lng = excluded.lng;
--> statement-breakpoint

ALTER TABLE "airports" ADD COLUMN "lat" double precision;--> statement-breakpoint
ALTER TABLE "airports" ADD COLUMN "lng" double precision;--> statement-breakpoint

-- Passenger terminal complexes, not the airfield reference points. Mirrored
-- in packages/db/src/seed.ts (AIRPORTS) — keep the two in step.
UPDATE airports SET lat = 40.6446, lng = -73.7797 WHERE code = 'JFK';--> statement-breakpoint
UPDATE airports SET lat = 40.7743, lng = -73.8722 WHERE code = 'LGA';--> statement-breakpoint
UPDATE airports SET lat = 40.6895, lng = -74.1787 WHERE code = 'EWR';--> statement-breakpoint

DO $$
DECLARE
  uncoordinated integer;
BEGIN
  SELECT count(*) INTO uncoordinated FROM airports WHERE lat IS NULL OR lng IS NULL;
  IF uncoordinated > 0 THEN
    RAISE EXCEPTION
      'airports: % row(s) have no coordinates. The airports_code_check CHECK is meant to make JFK/LGA/EWR the whole set — a fourth airport arrived without this migration learning about it.',
      uncoordinated;
  END IF;
END $$;--> statement-breakpoint

ALTER TABLE "airports" ALTER COLUMN "lat" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "airports" ALTER COLUMN "lng" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "airports" ADD CONSTRAINT "airports_lat_range_check" CHECK ("airports"."lat" between -90 and 90);--> statement-breakpoint
ALTER TABLE "airports" ADD CONSTRAINT "airports_lng_range_check" CHECK ("airports"."lng" between -180 and 180);--> statement-breakpoint

-- Backfill existing addresses. Only rows with no coordinate are touched, so a
-- precisely geocoded address (there are none today, there will be) is never
-- overwritten by a centroid. An unknown ZIP stays NULL: the ETA seam renders
-- "ETA on the way" for a missing coordinate rather than inventing a position.
DO $$
DECLARE
  filled integer;
  still_null integer;
BEGIN
  UPDATE addresses a
     SET lat = c.lat, lng = c.lng
    FROM zip_centroids c
   WHERE a.lat IS NULL
     AND a.lng IS NULL
     AND left(a.zip, 5) = c.zip;
  GET DIAGNOSTICS filled = ROW_COUNT;

  SELECT count(*) INTO still_null FROM addresses WHERE lat IS NULL OR lng IS NULL;

  RAISE NOTICE 'addresses: backfilled % row(s) from ZIP centroids; % row(s) left without coordinates (ZIP not in zip_centroids)', filled, still_null;

  IF still_null > 0 THEN
    RAISE NOTICE 'addresses without coordinates, by ZIP: %', (
      SELECT string_agg(zip || ' x' || n, ', ' ORDER BY zip)
        FROM (SELECT zip, count(*) AS n FROM addresses WHERE lat IS NULL OR lng IS NULL GROUP BY zip) s
    );
  END IF;
END $$;
